ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` SET OPTIONS(description="Entrada e saída diárias do Agenciamento: cards criados (data real em quantidade, estimada em quantidade_estimada) e entregues ao cliente (quantidade_saida: 1ª ida a Aguardando Feedback) nos boards 2024, 2025 e 2026 por dia, grupo de input, tipo de input e família, de 2024-10-01 até ontem, só combinações com entrada ou saída; e a situação hoje dos cards que entraram no dia (safra: entregue_no_mes, entregue_depois, nao_seguiu, em_andamento — foto do dia). Para tendência, previsão de demanda e relatório por safra; recortes na leitura. Recriada a cada execução. Regras: docs/tabelas/gld_agenciamento_entrada_diaria.md (PPD-GOLDEN-AGENCIAMENTO-MONDAY)");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN data SET OPTIONS(description="Dia (Brasília) da entrada (criado_em; no board 2026 com cadastro retroativo, a data_de_entrada; sem criado_em, data_de_saida − 5 dias úteis) ou da saída (1ª ida a Aguardando Feedback) dos cards contados na linha; de 2024-10-01 até ontem. Com grupo_input, tipo_de_input e familia, forma a chave");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN dia_semana SET OPTIONS(description="Dia da semana abreviado (seg, ter, qua, qui, sex, sáb, dom)");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN ano SET OPTIONS(description="Ano da data (calendário)");
