ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN inicio_semana SET OPTIONS(description="Segunda-feira que inicia a semana da data (agrupar por semana sem problema na virada do ano)");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN grupo_input SET OPTIONS(description="Mercado, Inbound, Proativo, Internos (ViU, Interna, Globo, ViU First, OTR) ou Sem tipo (vazio); Outros = tipo novo ainda sem grupo");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN tipo_de_input SET OPTIONS(description="Valor original da silver; vazio = Sem tipo");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN familia SET OPTIONS(description="Upfront, Levop, Mídia Kit, Análise, Defesa, Curadoria (pelo nome/marca), Card de Oportunidade (Levop), Curadoria Orçada, Defesas | Estudo Comercial (pelo tipo de output, com as variantes antigas de 2024/2025) ou Nenhuma; com mais de uma, vale a primeira desta ordem");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN quantidade SET OPTIONS(description="Cards que entraram no dia, com data real (criado_em; ou data_de_entrada no cadastro retroativo do board 2026: data_de_saida antes da criação e data_de_entrada até a data_de_saida)");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN quantidade_estimada SET OPTIONS(description="Cards que entraram no dia, com data estimada (data_de_saida − 5 dias úteis, calendário de feriados da SLA)");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN quantidade_saida SET OPTIONS(description="Cards entregues ao cliente no dia: 1ª entrada em Aguardando Feedback pelo log (board 2026) ou, sem ela, data_de_saida; saída antes da data de entrada do card (criação ou, no cadastro retroativo, data_de_entrada) fica fora");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN entregue_no_mes SET OPTIONS(description="Dos cards que entraram na linha (quantidade + quantidade_estimada): com saída válida (a da quantidade_saida, até ontem) no mesmo mês-calendário da data de entrada. Foto do dia: muda a cada execução");
ALTER TABLE `gglobo-viu-dados-hdg-prd.gold_monday.gld_agenciamento_entrada_diaria` ALTER COLUMN entregue_depois SET OPTIONS(description="Dos cards que entraram na linha: com saída válida em mês posterior ao da entrada. Foto do dia");
